async def test_events_arrive_while_the_response_is_still_open(async_client: AsyncTungo, server: MockServer) -> None:
    server.add("POST", CHAT, Reply(chunks=[TEXT_1, 0.6, TEXT_2, DONE]))
    started = time.monotonic()
    arrivals: list[float] = []
    async with await async_client.chat.create_stream("co_1", message="Сколько НДС?") as stream:
        async for _ in stream:
            arrivals.append(time.monotonic() - started)
    assert len(arrivals) == 3
    assert arrivals[0] < 0.4, "the first event must not wait for the end of the response"
    assert arrivals[1] >= 0.55
    request = server.requests[0]
    assert request.json() == {"message": "Сколько НДС?", "stream": True}
    assert request.headers["accept"] == "text/event-stream"
    assert request.headers["idempotency-key"]


async def test_events_are_typed_and_heartbeats_are_skipped(async_client: AsyncTungo, server: MockServer) -> None:
    future = sse("hologram", {"type": "hologram", "payload": {"a": 1}})
    server.add("POST", CHAT, Reply(chunks=[PING, TEXT_1, future, PING, DONE]))
    async with await async_client.chat.create_stream("co_1", message="?") as stream:
        events = [event async for event in stream]
    text, unknown, done = events
    assert isinstance(text, ChatEventText)
    assert (text.delta, text.step) == ("НДС ", 1)
    assert isinstance(unknown, UnknownVariant), "an event type added later must not break the stream"
    assert unknown.to_dict() == {"type": "hologram", "payload": {"a": 1}}
    assert isinstance(done, ChatEventDone)
    assert done.stop_reason == "end_turn"


